import { loadFont as loadCinzel } from "@remotion/google-fonts/Cinzel";
import { loadFont as loadGaramond } from "@remotion/google-fonts/EBGaramond";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// Cara da JRE (vestuário "do peão ao rei", luxo silencioso). Série da sigla: J = JORNADA.
// v3 (16/10): a voz da v2 ainda saiu com sotaque de Portugal. Voz nova: o locutor no modelo eleven_multilingual_v2, sem
// marcações (public/cara-da-jre/voz-v4.mp3, 23,0 s); a tabela abaixo converte o tempo dela no da voz v1. O resto é a v2.
// v2 (16/10): o dono achou a v1 "um pouco parada" e a voz saiu com sotaque de Portugal. Voz nova: o locutor com
// [Brazilian Portuguese accent] e "Jota" escrito por extenso (public/cara-da-jre/voz-v3.mp3, 23,6 s). As cenas continuam
// escritas nos tempos da voz v1; a tabela V3V1 converte, palavra por palavra. Mais movimento: câmera com inclinação e
// troca de plano a cada frase, texto entrando com escala, peão caindo no tabuleiro, câmera girando em volta dele.
// Identidade tirada da arte do manifesto: preto, dourado em degradê, serifa clássica em caixa alta espaçada, leão, coroa e peão.
// Frases em EB Garamond: a Cormorant saiu com o acento de "você" deslocado no render.
// Pouco material (só a arte com o logo) → motion: tudo desenhado. Caminho em perspectiva, escada com o peão subindo,
// tabuleiro em que o peão avança até a última casa e ganha a coroa, e o logo no fim.
// Limpo: fundo escuro liso com luz quente; o texto entra e fica parado; o movimento contínuo fica na câmera e nos desenhos.
// Tempos = tempos da locução (t = 0 é o começo do mp3; o vídeo tem LEAD de entrada).

const { fontFamily: CAPS } = loadCinzel("normal", { weights: ["400", "500", "600"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SERIF } = loadGaramond("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SERIF_I } = loadGaramond("italic", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });

export const JRE3_FPS = 30;
const JRE_FPS = JRE3_FPS;
// [tempo na voz v3, tempo na voz v1], uma linha por palavra-âncora; fora da tabela, inclinação 1
const V3V1: [number, number][] = [
  [0.11, 0.21], [1.29, 1.93], [3.13, 3.78], [3.19, 3.86], [3.79, 4.52], [4.37, 5.02], [5.01, 5.54], [6.5, 7.1], [7.38, 7.62], [8.44, 8.44], [8.86, 8.88], [9.5, 9.54], [10.12, 10.57], [10.46, 10.83], [11.54, 12.07], [11.8, 12.39], [13.3, 13.91], [13.52, 14.21], [14.96, 15.63], [15.44, 16.15], [16.32, 17.74], [16.56, 18.1], [16.86, 18.6], [17.02, 18.82], [17.3, 19.1], [18.29, 20.5], [18.39, 20.7], [18.69, 21.12], [18.85, 21.32], [19.11, 21.58], [19.43, 21.84], [20.13, 22.96], [20.41, 23.12], [20.93, 23.34], [21.81, 23.74], [22.15, 24.44], [22.27, 24.57], [22.61, 24.9],
];
const toV1 = (t: number) => {
  if (t <= V3V1[0][0]) return t - V3V1[0][0] + V3V1[0][1];
  for (let i = 1; i < V3V1.length; i++) if (t <= V3V1[i][0]) { const [a0, b0] = V3V1[i - 1], [a1, b1] = V3V1[i]; return b0 + ((t - a0) / (a1 - a0)) * (b1 - b0); }
  const [a, b] = V3V1[V3V1.length - 1]; return t - a + b;
};
const LEAD = 0.4;
const END = 3.3;
export const JRE3_FRAMES = Math.round((LEAD + 22.61 + END) * JRE_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.6) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const BG = "#0A0806";
const CREAM = "#F2E6CC";
const GOLD = "#D6B169";
const GOLD_GRAD = "linear-gradient(100deg,#8E6A2F 0%,#C9A25A 22%,#F6E2B0 40%,#FFF4D6 46%,#E2C17D 56%,#B08A45 78%,#8E6A2F 100%)";

// trocas de cena
const T2 = 3.5, T3 = 9.85, T4 = 16.95, T6 = 24.95;

// dourado com brilho passando (o brilho anda devagar, o texto fica parado)
const gold = (t: number, speed = 0.18, off = 0): React.CSSProperties => ({
  backgroundImage: GOLD_GRAD, backgroundSize: "260% 100%", backgroundPosition: `${(100 - ((t * speed * 100 + off) % 200)).toFixed(1)}% 50%`,
  WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent",
});

// texto: entra desfocado subindo pouco e assenta; sai desfocando no mesmo lugar
const blurIn = (t: number, at: number, out?: number, d = 0.5): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.25);
  return { opacity: Math.min(1, e * 1.5) * (1 - o), filter: `blur(${((1 - e) * 16 + o * 14).toFixed(1)}px)`, transform: `scale(${(1.22 - 0.22 * e + 0.06 * o).toFixed(4)})` };
};

type Seg = [string, boolean?];  // trecho, em dourado itálico
const Line: React.FC<{ t: number; at: number; out?: number; segs: Seg[]; size: number }> = ({ t, at, out, segs, size }) => (
  <div style={{ fontFamily: SERIF, fontWeight: 500, fontSize: size, lineHeight: 1.12, color: CREAM, whiteSpace: "nowrap", textAlign: "center", ...blurIn(t, at, out) }}>
    {segs.map(([s, g], i) => (
      <span key={i} style={g ? { fontFamily: SERIF_I, fontWeight: 600, ...gold(t, 0.16, i * 30) } : undefined}>{s}</span>
    ))}
  </div>
);
const Block: React.FC<{ children: React.ReactNode; top?: number }> = ({ children, top = 250 }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>{children}</div>
);

// luz quente de fundo
const Glow: React.FC<{ x?: number; y: number; r: number; a: number }> = ({ x = 540, y, r, a }) => (
  <div style={{ position: "absolute", left: x - r, top: y - r, width: r * 2, height: r * 2, borderRadius: "50%",
    background: `radial-gradient(circle, rgba(255,214,150,${a}) 0%, rgba(214,160,80,${a * 0.45}) 32%, rgba(120,80,30,0) 70%)` }} />
);

const GradDefs: React.FC<{ id: string }> = ({ id }) => (
  <defs>
    <linearGradient id={id} x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stopColor="#FFF0C8" /><stop offset="0.35" stopColor="#E6C47F" /><stop offset="0.7" stopColor="#B88F48" /><stop offset="1" stopColor="#7E5D27" />
    </linearGradient>
  </defs>
);
// peão de xadrez (base em y = 140 do viewBox)
const Pawn: React.FC<{ h: number; id: string }> = ({ h, id }) => (
  <svg width={(h * 100) / 140} height={h} viewBox="0 0 100 140" style={{ overflow: "visible", display: "block" }}>
    <GradDefs id={id} />
    <g fill={`url(#${id})`}>
      <circle cx="50" cy="24" r="18" />
      <ellipse cx="50" cy="48" rx="22" ry="6" />
      <path d="M37 52 C 39 76, 31 96, 22 110 L 78 110 C 69 96, 61 76, 63 52 Z" />
      <rect x="15" y="108" width="70" height="13" rx="4" />
      <rect x="7" y="122" width="86" height="18" rx="5" />
    </g>
  </svg>
);
const Crown: React.FC<{ w: number; id: string }> = ({ w, id }) => (
  <svg width={w} height={(w * 92) / 120} viewBox="0 0 120 92" style={{ overflow: "visible", display: "block" }}>
    <GradDefs id={id} />
    <g fill={`url(#${id})`}>
      <path d="M12 70 L18 26 L40 50 L60 12 L80 50 L102 26 L108 70 Z" />
      <rect x="8" y="74" width="104" height="14" rx="3" />
      <path d="M60 0 L66 9 L60 18 L54 9 Z" /><circle cx="18" cy="22" r="6" /><circle cx="102" cy="22" r="6" />
    </g>
  </svg>
);

// ───────── cena 1: J… Jornada ─────────
const Abertura: React.FC<{ t: number }> = ({ t }) => {
  const e = k(t, 0.05, 0.75);
  const ex = io(t, T2 - 0.25, T2 + 0.3);                 // mergulho dentro do J
  const cam = 1 + 0.12 * io(t, -0.4, 1.9) + 0.12 * lin(t, 0.5, 1.9) + 0.14 * k(t, 1.9, 0.7) + 0.05 * lin(t, 2.6, T2) + ex * 2.4;
  const rot = -4 * (1 - k(t, 0.1, 1.4)) - 2.5 * lin(t, 0.6, 1.9) + 2.5 * k(t, 1.9, 0.5) + 2 * k(t, 1.9, 0.8) - 2 * lin(t, 2.7, T2);
  const shaft = interpolate(t, [-0.4, 1.7, 1.71, T2], [-760, 760, -760, 760], { ...cl, easing: INOUT });
  const letters = "JORNADA".split("");
  return (
    <AbsoluteFill style={{ opacity: 1 - lin(t, T2, T2 + 0.3), transform: `scale(${cam.toFixed(4)}) rotate(${rot.toFixed(2)}deg)`, transformOrigin: "540px 880px" }}>
      <Glow y={900} r={620 + 60 * Math.sin(t * 1.3)} a={0.2 * e} />
      <div style={{ position: "absolute", left: 540 - 170 + shaft, top: -300, width: 340, height: 2600, transform: "rotate(18deg)", background: "linear-gradient(90deg, rgba(255,215,150,0) 0%, rgba(255,215,150,0.09) 50%, rgba(255,215,150,0) 100%)" }} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 370, textAlign: "center", fontFamily: CAPS, fontWeight: 500, fontSize: 780, lineHeight: 1,
        ...gold(t, 0.55, 40), opacity: Math.min(1, e * 1.4), filter: `blur(${((1 - e) * 26).toFixed(1)}px)`, transform: `translateY(${((1 - e) * -260).toFixed(1)}px) scale(${(2.2 - 1.2 * e).toFixed(4)})` }}>J</div>
      <div style={{ position: "absolute", left: 120, right: 120, top: 1250, display: "flex", justifyContent: "center" }}>
        {letters.map((c, i) => (
          <span key={i} style={{ fontFamily: CAPS, fontWeight: 500, fontSize: 100, letterSpacing: "0.2em", marginRight: i === letters.length - 1 ? "-0.2em" : 0, ...gold(t, 0.2, i * 12), ...blurIn(t, 1.93 + i * 0.06, undefined, 0.6) }}>{c}</span>
        ))}
      </div>
      <div style={{ position: "absolute", left: 540 - 300 * k(t, 2.2, 0.9), width: 600 * k(t, 2.2, 0.9), top: 1415, height: 2, background: `linear-gradient(90deg, transparent, ${GOLD}, transparent)` }} />
    </AbsoluteFill>
  );
};

// ───────── cena 2: o caminho ─────────
const HZ = 1000, F = 900;
const Caminho: React.FC<{ t: number }> = ({ t }) => {
  const enter = io(t, T2 - 0.05, T2 + 0.6);
  const exit = io(t, T3 - 0.35, T3 + 0.3);
  const walk = 2.6 * (t - T2);
  const Xw = (w: number) => 1.7 * Math.sin(0.2 * w) + 0.5 * Math.sin(0.47 * w + 1);
  const cx = (z: number) => 540 + (F * (Xw(z + walk) - Xw(1 + walk))) / z;
  const sy = (z: number) => HZ + 920 / z;
  const zmax = 1 + 44 * Math.pow(k(t, 3.65, 1.6), 1.3);
  const zs: number[] = [];
  for (let z = 0.75; z <= zmax; z *= 1.045) zs.push(z);
  zs.push(zmax);
  const L = zs.map((z) => [cx(z) - (F * 0.6) / z, sy(z)]);
  const R = zs.map((z) => [cx(z) + (F * 0.6) / z, sy(z)]);
  const pts = (a: number[][]) => a.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(" ");
  const stones: React.ReactNode[] = [];
  const fr = walk % 1;
  for (let i = 1; i < 44; i++) {
    const z = i - fr + 0.6;
    if (z < 1 || z > zmax) continue;
    const rx = (F * 0.07) / z;
    stones.push(<ellipse key={i} cx={cx(z)} cy={sy(z)} rx={rx} ry={rx * 0.28} fill={GOLD} opacity={Math.min(0.75, 1.6 / Math.sqrt(z)) * lin(z, 1, 1.4)} />);
  }
  // peão andando à frente
  const pe = k(t, 6.95, 0.5);
  const pz = 3.4 + 0.25 * Math.sin(t * 0.7);
  const ph = (F * 1.15) / pz;
  const hop = Math.abs(Math.sin(walk * Math.PI)) * 7;
  // plano 1: aberto, entrando no caminho; plano 2 (a partir de 7,0): perto do peão, câmera mais baixa
  const cut = t >= 7.0 ? 1 : 0;
  const cut2 = t >= 4.9 && t < 7.0;
  const zoom = cut ? 1.32 + 0.1 * lin(t, 7.0, T3) : cut2 ? 1.5 + 0.15 * lin(t, 4.9, 7.0) : 1.18 - 0.18 * enter + 0.12 * lin(t, T2, 4.9);
  const bank = 3.2 * Math.sin(0.2 * (walk + 2)) * (cut ? 0.6 : 1);
  const focusX = cut ? cx(3.4) : cut2 ? cx(6) : 540, focusY = cut ? 1180 : cut2 ? 1060 : 1000;
  return (
    <AbsoluteFill style={{ opacity: enter * (1 - exit), transform: `translateY(${(exit * 520).toFixed(1)}px)` }}>
     <AbsoluteFill style={{ transform: `rotate(${bank.toFixed(2)}deg) scale(${zoom.toFixed(4)})`, transformOrigin: `${focusX.toFixed(1)}px ${focusY.toFixed(1)}px` }}>
      <Glow y={HZ - 20} r={560 + 40 * Math.sin(t)} a={0.34 * k(t, 3.6, 1.4)} />
      <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}>
        <defs>
          <linearGradient id="jre-road" x1="0" y1="1" x2="0" y2="0">
            <stop offset="0" stopColor="#130E08" /><stop offset="1" stopColor="#4A3519" />
          </linearGradient>
          <linearGradient id="jre-edge" x1="0" y1="1" x2="0" y2="0">
            <stop offset="0" stopColor="#E9CB86" stopOpacity="0.9" /><stop offset="1" stopColor="#FFE7B3" stopOpacity="0.25" />
          </linearGradient>
        </defs>
        <line x1={540 - 480 * k(t, 3.6, 1.2)} x2={540 + 480 * k(t, 3.6, 1.2)} y1={HZ} y2={HZ} stroke={GOLD} strokeOpacity={0.35} strokeWidth={1.5} />
        <polygon points={pts([...L, ...[...R].reverse()])} fill="url(#jre-road)" opacity={0.95} />
        {stones}
        <polyline points={pts(L)} fill="none" stroke="url(#jre-edge)" strokeWidth={3} />
        <polyline points={pts(R)} fill="none" stroke="url(#jre-edge)" strokeWidth={3} />
      </svg>
      <div style={{ position: "absolute", left: cx(pz) - (ph * 50) / 140, top: sy(pz) - ph - hop, opacity: pe, filter: `blur(${((1 - pe) * 12).toFixed(1)}px) drop-shadow(0 0 26px rgba(255,210,140,0.35))` }}>
        <Pawn h={ph} id="jre-p1" />
      </div>
     </AbsoluteFill>
      <Block>
        <Line t={t} at={3.78} out={6.75} size={78} segs={[["A jornada não é apenas"]]} />
        <Line t={t} at={4.9} out={6.75} size={78} segs={[["o "], ["caminho", true], [" que percorremos."]]} />
      </Block>
      <Block>
        <Line t={t} at={7.1} size={78} segs={[["É "], ["quem nos tornamos", true]]} />
        <Line t={t} at={8.44} size={78} segs={[["enquanto caminhamos."]]} />
      </Block>
    </AbsoluteFill>
  );
};

// ───────── cena 3: a escada (passo, superação, vitória) ─────────
const STEP = 112, SX = 150, SY = 1700, DX = 70, DY = -46;
const LIT = [10.62, 10.95, 12.12, 12.4, 12.68, 13.96, 14.22];
const Escada: React.FC<{ t: number }> = ({ t }) => {
  const enter = io(t, T3 - 0.3, T3 + 0.45);
  const exit = io(t, T4 - 0.35, T4 + 0.3);
  // posição do peão: degrau (pode ser fracionário no pulo)
  let pos = -0.6;
  LIT.forEach((a) => { pos += io(t, a - 0.05, a + 0.28); });
  pos = Math.max(-0.6, pos);
  const fr = pos - Math.floor(pos);
  const hop = Math.sin(fr * Math.PI) * 60;
  const stepX = (i: number) => SX + i * STEP;
  const stepY = (i: number) => SY - (i + 1) * STEP;
  const px = stepX(pos) + STEP / 2 + DX / 2;
  const py = stepY(Math.max(pos, -1)) + DY / 2 - hop;
  const crownIn = k(t, 14.2, 0.8);
  const crownDrop = io(t, 15.55, 16.0);
  const pullback = io(t, 15.5, 16.8);
  // câmera: segue o peão de perto e abre para mostrar a escada inteira em "tudo faz parte"
  const punch = [10.56, 12.07, 13.91, 15.63].reduce((acc, a) => acc + 0.07 * k(t, a, 0.45) * (1 - lin(t, a + 0.45, a + 1.4)), 0);
  const sc = 1.16 + 0.14 * io(t, 13.9, 15.6) - 0.26 * pullback + 0.05 * (1 - enter) + punch + 0.05 * lin(t, 16.0, T4);
  const srot = -2.5 + 4 * lin(t, T3, T4);
  const fx = (0.45 * px + 0.55 * 560) * (1 - pullback) + 560 * pullback;
  const fy = (py - 60) * (1 - pullback) + 1240 * pullback;
  const tx = 540 - fx * sc, ty = 1060 - fy * sc;
  const steps: React.ReactNode[] = [];
  for (let i = 0; i < 7; i++) {
    const x = stepX(i), y = stepY(i);
    const lit = k(t, LIT[i], 0.5);
    const shine = 0.55 + 0.45 * lit;
    steps.push(
      <g key={i}>
        <polygon points={`${x},${y} ${x + STEP},${y} ${x + STEP + DX},${y + DY} ${x + DX},${y + DY}`} fill={`rgba(214,177,105,${(0.1 + 0.55 * lit).toFixed(3)})`} stroke="#E8CB88" strokeOpacity={shine} strokeWidth={2.5} />
        <rect x={x} y={y} width={STEP} height={SY - y} fill="#15100A" stroke="#C9A25A" strokeOpacity={0.35 + 0.4 * lit} strokeWidth={2} />
      </g>,
    );
  }
  const ph = 150;
  const crownY = -ph * 0.06 - 140 * (1 - crownDrop) - 18 * (1 - crownIn);
  const words: [number, number | undefined, Seg[]][] = [
    [10.56, 11.85, [["Cada "], ["passo.", true]]],
    [12.07, 13.68, [["Cada "], ["superação.", true]]],
    [13.91, 15.4, [["Cada "], ["vitória.", true]]],
    [15.63, undefined, [["Tudo faz "], ["parte.", true]]],
  ];
  return (
    <AbsoluteFill style={{ opacity: enter * (1 - exit), filter: exit > 0 ? `blur(${(exit * 18).toFixed(1)}px)` : undefined, transform: `translateY(${((1 - enter) * -520).toFixed(1)}px)` }}>
      <Glow x={stepX(6) + 90} y={stepY(6) - 160} r={520} a={0.12 + 0.2 * k(t, 13.96, 1)} />
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, transform: `rotate(${srot.toFixed(2)}deg) translate(${tx.toFixed(1)}px, ${ty.toFixed(1)}px) scale(${sc.toFixed(4)})`, transformOrigin: "540px 1060px" }}>
        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0, overflow: "visible" }}>{steps}</svg>
        <div style={{ position: "absolute", left: px - (ph * 50) / 140, top: py - ph, filter: "drop-shadow(0 0 22px rgba(255,210,140,0.4))", opacity: k(t, T3, 0.5) }}>
          <Pawn h={ph} id="jre-p2" />
          <div style={{ position: "absolute", left: (ph * 50) / 140 - 45, top: crownY, opacity: crownIn, filter: `blur(${((1 - crownIn) * 10).toFixed(1)}px)` }}>
            <Crown w={90} id="jre-c1" />
          </div>
        </div>
      </div>
      <Block top={300}>
        {words.map(([a, o, s], i) => (
          <div key={i} style={{ position: "absolute", top: 0, left: 0, right: 0, display: "flex", justifyContent: "center" }}>
            <Line t={t} at={a} out={o} size={118} segs={s} />
          </div>
        ))}
      </Block>
    </AbsoluteFill>
  );
};

// ───────── cena 4/5: o tabuleiro (onde começa, para onde vai, quem se torna) ─────────
const BH = 2.3, BF = 820, BHZ = 740;
const Tabuleiro: React.FC<{ t: number }> = ({ t }) => {
  const enter = io(t, T4 - 0.2, T4 + 0.6);
  const exit = io(t, T6 - 0.2, T6 + 0.25);
  // peão anda da casa 0 até a 7, uma casa por vez, junto com "está indo"
  const n = 7, a0 = 20.55, a1 = 23.55;
  let wp = 0.5;
  for (let i = 0; i < n; i++) wp += io(t, a0 + (i * (a1 - a0)) / n, a0 + ((i + 0.85) * (a1 - a0)) / n);
  const hop = Math.sin((wp - 0.5 - Math.floor(wp - 0.5)) * Math.PI);
  const wc = wp - 5.6 + 2.0 * io(t, T4, a0) - 1.2 * (1 - enter) + 0.9 * io(t, 23.6, 24.9);
  const camX = 1.8 - 1.8 * io(t, T4, 21.4) + 0.35 * Math.sin((t - 21.4) * 1.6) * lin(t, 21.4, 22.2) * (1 - lin(t, 23.4, 24.2));
  const proj = (X: number, W: number) => { const z = Math.max(0.15, W - wc); return [540 + (BF * (X - camX)) / z, BHZ + (BF * BH) / z]; };
  const sq: React.ReactNode[] = [];
  for (let r = -7; r < 8; r++) {
    for (let c = -4; c <= 4; c++) {
      const X0 = c - 0.5, X1 = c + 0.5, W0 = r, W1 = r + 1;
      if (W0 - wc < 0.2 && W1 - wc < 0.2) continue;
      const W0c = Math.max(W0, wc + 0.2);
      const p = [proj(X0, W0c), proj(X1, W0c), proj(X1, W1), proj(X0, W1)];
      const z = (W0c + W1) / 2 - wc;
      const light = (r + c) % 2 === 0;
      const fade = Math.min(1, 2.8 / z) * (1 - Math.abs(c) / 6);
      sq.push(<polygon key={`${r}${c}`} points={p.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(" ")} fill={light ? "#2C2214" : "#0F0B07"} stroke="#D6B169" strokeOpacity={0.32 * fade} strokeWidth={1.5} opacity={Math.min(1, 0.25 + fade)} />);
    }
  }
  const [bx, by] = proj(0, wp);
  const zp = wp - wc;
  const ph = (BF * 1.25) / zp;
  const promo = k(t, 23.75, 0.9);
  const drop = interpolate(t, [17.45, 17.95], [0, 1], { ...cl, easing: Easing.bounce });
  const crownDrop = io(t, 24.0, 24.55);
  const flash = Math.max(0, 1 - Math.abs(t - 24.55) / 0.25) * 0.2;
  const [ex, ey] = proj(0, 8);
  return (
    <AbsoluteFill style={{ opacity: enter * (1 - exit) }}>
      <Glow x={ex} y={ey - 30} r={520 + 120 * promo} a={0.18 + 0.2 * lin(t, a0, a1)} />
      <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}>{sq}</svg>
      <Glow x={bx} y={by - ph * 0.5} r={ph * 1.1} a={0.12 + 0.35 * promo} />
      <div style={{ position: "absolute", left: bx - (ph * 50) / 140, top: by - ph - hop * 48 - 700 * Math.pow(1 - drop, 2), filter: "drop-shadow(0 0 24px rgba(255,210,140,0.4))", opacity: Math.min(1, drop * 3) }}>
        <Pawn h={ph} id="jre-p3" />
        <div style={{ position: "absolute", left: (ph * 50) / 140 - ph * 0.3, top: -ph * 0.36 - ph * 0.9 * (1 - crownDrop), opacity: k(t, 23.9, 0.4) }}>
          <Crown w={ph * 0.6} id="jre-c2" />
        </div>
      </div>
      <AbsoluteFill style={{ background: "#FFE9BF", opacity: flash, mixBlendMode: "screen" }} />
      <Block>
        <Line t={t} at={17.73} out={20.15} size={84} segs={[["Não é sobre"]]} />
        <Line t={t} at={18.55} out={20.15} size={84} segs={[["onde você "], ["começa.", true]]} />
      </Block>
      <Block>
        <Line t={t} at={20.48} out={22.65} size={84} segs={[["É sobre onde"]]} />
        <Line t={t} at={21.1} out={22.65} size={84} segs={[["você "], ["está indo.", true]]} />
      </Block>
      <Block>
        <Line t={t} at={22.94} size={84} segs={[["E quem você"]]} />
        <Line t={t} at={23.6} size={84} segs={[["se torna "], ["no caminho.", true]]} />
      </Block>
    </AbsoluteFill>
  );
};

// ───────── cena 6: a marca ─────────
const Marca: React.FC<{ t: number }> = ({ t }) => {
  const e = k(t, T6 - 0.05, 1.1);
  const sweep = lin(t, T6 + 0.5, T6 + 1.5) + lin(t, T6 + 1.6, T6 + 2.5) + lin(t, T6 + 2.6, T6 + 3.5);
  const W = 640, H = (W * 686) / 712;
  const cam = 1.1 - 0.1 * e + 0.12 * lin(t, T6, T6 + 3.6);
  return (
    <AbsoluteFill style={{ opacity: lin(t, T6 - 0.1, T6 + 0.35), transform: `scale(${cam.toFixed(4)})` }}>
      <Glow y={880} r={640} a={0.2 * e} />
      <div style={{ position: "absolute", left: 540 - W / 2, top: 500, width: W, height: H, opacity: e, filter: `blur(${((1 - e) * 20).toFixed(1)}px)`, transform: `scale(${(1.4 - 0.4 * e).toFixed(4)}) rotate(${(-6 * (1 - e)).toFixed(2)}deg)` }}>
        <Img src={staticFile("cara-da-jre/logo.png")} style={{ width: W, height: H }} />
        <div style={{ position: "absolute", inset: 0, WebkitMaskImage: `url(${staticFile("cara-da-jre/logo.png")})`, WebkitMaskSize: "100% 100%",
          background: `linear-gradient(105deg, transparent ${((sweep % 1.0001) * 160 - 40).toFixed(1)}%, rgba(255,246,220,0.85) ${((sweep % 1.0001) * 160 - 25).toFixed(1)}%, transparent ${((sweep % 1.0001) * 160 - 10).toFixed(1)}%)`, mixBlendMode: "screen" }} />
      </div>
      <div style={{ position: "absolute", left: 120, right: 120, top: 1230, textAlign: "center", fontFamily: CAPS, fontWeight: 500, fontSize: 62, letterSpacing: "0.22em", marginRight: "-0.22em", ...gold(t, 0.2), ...blurIn(t, T6 + 0.75) }}>DO PEÃO AO REI</div>
      <div style={{ position: "absolute", left: 540 - 260 * k(t, T6 + 1.1, 0.9), width: 520 * k(t, T6 + 1.1, 0.9), top: 1336, height: 2, background: `linear-gradient(90deg, transparent, ${GOLD}, transparent)` }} />
      <div style={{ position: "absolute", left: 120, right: 120, top: 1372, textAlign: "center", fontFamily: CAPS, fontWeight: 400, fontSize: 25, letterSpacing: "0.3em", color: CREAM, opacity: 0.85, ...blurIn(t, T6 + 1.3) }}>FEITO PARA QUEM DITA AS REGRAS.</div>
    </AbsoluteFill>
  );
};

export const JornadaV3: React.FC = () => {
  const frame = useCurrentFrame();
  const t = toV1(frame / JRE_FPS - LEAD);
  const near = (a: number, b: number) => t > a - 0.8 && t < b + 0.8;
  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      {near(-1, T2) && <Abertura t={t} />}
      {near(T2, T3) && <Caminho t={t} />}
      {near(T3, T4) && <Escada t={t} />}
      {near(T4, T6) && <Tabuleiro t={t} />}
      {t > T6 - 0.6 && <Marca t={t} />}
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 50%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.55) 100%)", pointerEvents: "none" }} />
    </AbsoluteFill>
  );
};

